@pytest.fixture(scope="module")
def css_rules(css_content: str) -> dict[str, str]:
    """
    Parse top-level CSS rules into a mapping of selector -> rule body.

    Handles nested braces (e.g., @media blocks) by tracking brace depth.
    Returns only top-level rules; nested rules are embedded in the body.
    """
    rules: dict[str, str] = {}
    selector_buffer: list[str] = []
    body_buffer: list[str] = []
    depth = 0
    current_selector: str | None = None

    for line in css_content.splitlines():
        stripped = line.strip()

        if not stripped:
            continue

        # Detect selector start (no opening brace yet, depth == 0)
        if depth == 0 and "{" not in stripped and "}" not in stripped:
            # Accumulate selector lines (could be multi-line selectors)
            selector_buffer.append(stripped)
            continue

        # Handle opening brace
        if "{" in stripped:
            # If we have a pending selector, finalize it
            if selector_buffer and depth == 0:
                current_selector = " ".join(selector_buffer).strip()
                selector_buffer = []
            depth += stripped.count("{")
            # Add the line to body (including the brace line for context)
            body_buffer.append(stripped)
            continue

        # Handle closing brace
        if "}" in stripped:
            depth -= stripped.count("}")
            body_buffer.append(stripped)
            if depth == 0:
                # Rule complete
                if current_selector:
                    rules[current_selector] = "\n".join(body_buffer).strip()
                current_selector = None
                body_buffer = []
            continue

        # Inside a rule body
        if depth > 0:
            body_buffer.append(stripped)

    # Handle case where file ends without closing brace (malformed)
    if current_selector and body_buffer:
        rules[current_selector] = "\n".join(body_buffer).strip()

    return rules


