class TestResponsiveDesign:
    """Validate responsive breakpoint usage."""

    def test_css_has_media_queries(self, media_queries: list[str]):
        """The CSS must contain at least one @media query."""
        assert media_queries, "No @media queries found in the CSS file"

    def test_expected_breakpoints_used(self, css_content: str):
        """All expected breakpoints should appear in media queries."""
        missing = [
            bp for bp in EXPECTED_BREAKPOINTS
            if bp not in css_content
        ]
        assert not missing, f"Missing expected breakpoints: {missing}"

    def test_media_query_syntax_valid(self, media_queries: list[str]):
        """Media queries must use valid min-width/max-width syntax."""
        valid_pattern = re.compile(
            r"^@media\s+(?:only\s+)?(?:screen|all)?\s*(?:and\s*)?"
            r"\((?:min|max)-width\s*:\s*\d+(?:\.\d+)?(?:px|em|rem)\)"
            r"(?:\s*and\s*\((?:min|max)-width\s*:\s*\d+(?:\.\d+)?(?:px|em|rem)\))*$"
        )
        invalid = [mq for mq in media_queries if not valid_pattern.match(mq)]
        assert not invalid, f"Invalid media query syntax: {invalid}"

    def test_media_queries_have_rules(self, css_rules: dict[str, str], media_queries: list[str]):
        """Each media query must contain at least one nested rule."""
        for mq in media_queries:
            body = css_rules[mq]
            # Check for at least one selector inside the media block
            assert re.search(r"[.#][a-zA-Z][a-zA-Z0-9_-]*\s*\{", body), (
                f"Media query '{mq}' contains no nested rules"
            )

    def test_mobile_first_pattern(self, css_content: str):
        """Base styles should come before media queries (mobile-first)."""
        base_rule_pos = css_content.find("{")
        first_media_pos = css_content.find("@media")
        assert first_media_pos == -1 or base_rule_pos < first_media_pos, (
            "Base styles should be defined before media queries (mobile-first approach)"
        )


