class TestSelectorConsistency:
    """Validate selector naming conventions and structure."""

    def test_selectors_follow_bem_convention(self, all_selectors: list[str]):
        """All class selectors must follow BEM-like naming for CSS Modules."""
        non_bem = []
        for sel in all_selectors:
            # Extract class names (e.g., .block__element--modifier)
            classes = re.findall(r"\.([a-zA-Z][a-zA-Z0-9_-]*)", sel)
            for cls in classes:
                if not BEM_PATTERN.match(cls):
                    non_bem.append(cls)
        assert not non_bem, f"Selectors not following BEM convention: {non_bem}"

    def test_no_html_element_selectors(self, all_selectors: list[str]):
        """Selectors must not target bare HTML elements."""
        forbidden = []
        for sel in all_selectors:
            # Check if selector is just an element name (no . or # prefix)
            if re.match(r"^[a-zA-Z][a-zA-Z0-9]*$", sel):
                forbidden.append(sel)
        assert not forbidden, f"Bare HTML element selectors found: {forbidden}"

    def test_no_id_selectors(self, all_selectors: list[str]):
        """Selectors must not use IDs (CSS Modules should use classes only)."""
        id_selectors = [sel for sel in all_selectors if sel.startswith("#")]
        assert not id_selectors, f"ID selectors found: {id_selectors}"

    def test_no_universal_selectors(self, all_selectors: list[str]):
        """Selectors must not use the universal selector (*)."""
        universal = [sel for sel in all_selectors if "*" in sel]
        assert not universal, f"Universal selectors found: {universal}"

    def test_no_duplicate_selectors(self, regular_selectors: list[str]):
        """No duplicate top-level selectors should exist."""
        duplicates = [sel for sel in set(regular_selectors) if regular_selectors.count(sel) > 1]
        assert not duplicates, f"Duplicate selectors found: {duplicates}"

    def test_no_empty_rule_bodies(self, css_rules: dict[str, str]):
        """No rule should have an empty body."""
        empty = [sel for sel, body in css_rules.items() if not body.strip()]
        assert not empty, f"Empty rule bodies found for: {empty}"

    def test_pseudo_classes_used(self, css_content: str):
        """The CSS should use pseudo-classes for interactivity (hover, focus, etc.)."""
