# ---------------------------------------------------------------------------
# Accessibility Tests
# ---------------------------------------------------------------------------

class TestAccessibility:
    """Validate the CSS supports accessibility requirements."""

    def test_css_focus_visible_styles(self, css_content: str):
        """The CSS should define :focus-visible styles for keyboard navigation."""
        assert ":focus-visible" in css_content or ":focus" in css_content, (
            "No focus styles found. Keyboard navigation requires visible focus indicators."
        )

    def test_css_color_contrast_hints(self, css_content: str):
        """The CSS should use colors that suggest good contrast (dark text on light bg)."""
        # Check for common high-contrast color pairs
        has_dark_text = bool(re.search(r"color\s*:\s*(#(?:[0-3][0-9a-fA-F]){3}|#(?:[0-3][0-9a-fA-F]){6}|black|#000)", css_content))
        has_light_bg = bool(re.search(r"background(?:-color)?\s*:\s*(#(?:[f-e][0-9a-fA-F]){3}|#(?:[f-e][0-9a-fA-F]){6}|white|#fff)", css_content))
        assert has_dark_text and has_light_bg, (
            "No clear high-contrast color scheme detected. Ensure text is readable."
        )

    def test_css_font_sizes_accessible(self, css_content: str):
        """Font sizes should be at least 14px equivalent (0.875rem)."""
        small_fonts = re.findall(r"font-size\s*:\s*(\d+(?:\.\d+)?)(px|rem|em)", css_content)
        for size, unit in small_fonts:
            value = float(size)
            if unit == "px" and value < 14:
                pytest.fail(f"Font size {size}{unit} is below 14px accessibility minimum")
            elif unit == "rem" and value < 0.875:
                pytest.fail(f"Font size {size}{unit} is below 0.875rem accessibility minimum")
            elif unit == "em" and value < 0.875:
                pytest.fail(f"Font size {size}{unit} is below 0.875em accessibility minimum")

    def test_css_spacing_adequate(self, css_content: str):
        """Spacing should be adequate for touch targets (min 44px for interactive elements)."""
        # Check for padding on interactive elements
        interactive_padding = re.findall(
            r"(?:button|a|input|select|textarea)[^{]*\{[^}]*padding\s*:\s*(\d+(?:\.\d+)?)(px|rem|em)",
            css_content,
            re.DOTALL
        )
        for size, unit in interactive_padding:
            value = float(size)
            if unit == "px" and value < 44:
                pytest.fail(f"Interactive element padding {size}{unit} is below 44px touch target minimum")
            elif unit == "rem" and value < 2.75:
                pytest.fail(f"Interactive element padding {size}{unit} is below 2.75rem touch target minimum")


